<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Fine management';$basePath='../';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];if(in_array($status,['paid','waived'],true)){$pdo->prepare('UPDATE fines SET status=?,paid_at=NOW(),note=? WHERE id=?')->execute([$status,trim($_POST['note']??''),$id]);audit($pdo,'Fine '.$status,'Fine #'.$id);flash('success','Fine updated.');}redirect('fines.php');}$fines=$pdo->query('SELECT f.*,m.name member_name,m.member_code,b.title FROM fines f JOIN members m ON m.id=f.member_id JOIN books b ON b.id=f.book_id ORDER BY f.id DESC')->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="panel"><div class="panel-head"><div><h3>Fine ledger</h3><p>Final fines are recorded when an administrator processes a return.</p></div></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Book</th><th>Amount</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($fines as $f):?><tr><td><?=e($f['member_name'])?><small><?=e($f['member_code'])?></small></td><td><?=e($f['title'])?></td><td><b><?=money($f['amount'])?></b></td><td><span class="pill <?=$f['status']==='unpaid'?'danger':'success'?>"><?=$f['status']?></span></td><td><?php if($f['status']==='unpaid'):?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$f['id']?>"><select name="status"><option value="paid">Mark paid</option><option value="waived">Waive</option></select><input name="note" placeholder="Note (optional)"><button class="btn small">Save</button></form><?php else:?><?=e($f['note']??'—')?><?php endif;?></td></tr><?php endforeach;?><?php if(!$fines):?><tr><td colspan="5" class="empty">No fines recorded.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
